import { ProjectParamsSchema, VariantParamsSchema } from './schemas';
import { Router } from 'express';
import { z } from 'zod';
import type { LibraryRouteServices } from './types';
import type {
  DirectionPreviewResponse,
  DirectionUpdateResponse,
} from '../../types/api-responses';

const VariantUpdateSchema = z.object({
  label: z.string().trim().min(1).max(200).optional(),
  status: z.literal('removed').optional(),
});

export const createVariantRoutes = ({
  library,
  previews,
  track,
}: LibraryRouteServices): Router => {
  const router = Router();
  router.get('/projects/:projectId/variants', async (req, res) => {
    res.json({
      variants: await library.listVariants(
        ProjectParamsSchema.parse(req.params).projectId,
      ),
    });
  });
  router.post(
    '/projects/:projectId/variants/:sessionId/:variantId/preview',
    track('preview_open'),
    async (req, res) => {
      res.json({
        url: await previews.url(VariantParamsSchema.parse(req.params)),
      } satisfies DirectionPreviewResponse);
    },
  );
  router.patch(
    '/projects/:projectId/variants/:sessionId/:variantId',
    track('direction_update'),
    async (req, res) => {
      const update = VariantUpdateSchema.parse(req.body);
      await library.updateVariant({
        ...VariantParamsSchema.parse(req.params),
        ...update,
      });
      res.json({ saved: true } satisfies DirectionUpdateResponse);
    },
  );
  return router;
};
